#' Generate offspring for a healthcare-worker (HCW) parent with work-place and post-admission thinning
#'
#' Simulates secondary infections (offspring) generated by a **healthcare-worker** parent.
#' The number of candidate offspring is drawn from a Negative Binomial distribution.
#' Candidate infection times are drawn from a **truncated Gamma** generation-time distribution
#' on \eqn{[0, t_\mathrm{outcome}]}. For HCW parents, **pre-admission** candidate infections
#' may occur in the **hospital** (while working) or in the **community**: each pre-admission
#' event is assigned to the hospital with probability \code{prob_hospital_cond_hcw_preAdm}
#' and to the community otherwise. Candidate events occurring at or after the parent's
#' hospitalisation time are always labelled \code{"hospital"}. Each offspring is then assigned
#' a class (\code{"HCW"} or \code{"genPop"}) using setting-specific probabilities, and hospital
#' events are thinned by three multiplicatively-combined protective layers, each applied only
#' where it is relevant:
#' \itemize{
#'   \item Source PPE worn by the still-working HCW parent applies to all pre-admission
#'         hospital events (any recipient class).
#'   \item Receiver PPE worn by HCW recipients while treating the source applies to all
#'         hospital events with an HCW recipient (pre- or post-admission).
#'   \item Hospital quarantine applies to all post-admission hospital events (source is now
#'         a hospitalised, isolated HCW patient).
#' }
#' Hospital keep-probability is therefore
#' \eqn{(1 - \mathrm{ppe\_cov}(t)\,\mathrm{ppe\_eff} \cdot \mathbb{1}[\text{pre-admission}]) (1 - \mathrm{ppe\_cov}(t)\,\mathrm{ppe\_eff} \cdot \mathbb{1}[\text{HCW recipient}]) (1 - \mathrm{hq}(t) \cdot \mathbb{1}[\text{post-admission}])},
#' where each PPE layer thins by coverage times conditional efficacy. Time-varying inputs are
#' resolved at the absolute calendar time of each candidate hospital transmission event.
#' The post-admission hospital quarantine efficacy is calculated internally as a
#' \code{prop_etu(t)}-weighted mixture of the (fixed) ETU and general-hospital quarantine efficacies.
#'
#' @param parent_info One-row data.frame/list containing parent infection, hospitalisation and outcome times.
#' @param mn_offspring_hcw Positive numeric or function(t). Mean of the Negative Binomial offspring
#'   distribution for HCW parents (\code{rnbinom(mu = ..., size = ...)}). May be supplied as a single
#'   positive scalar or as a function of absolute calendar time (e.g. built with
#'   \code{\link{make_time_varying}}); when time-varying it is resolved at the parent's absolute
#'   infection time.
#' @param overdisp_offspring_hcw Positive numeric. Negative Binomial \code{size} (overdispersion)
#'   for HCW parents.
#' @param Tg_shape_hcw Positive numeric. Shape of the Gamma generation-time distribution
#'   for HCW parents (before truncation).
#' @param Tg_rate_hcw Positive numeric. Rate of the Gamma generation-time distribution
#'   for HCW parents (before truncation). Mean GT is \code{Tg_shape_hcw / Tg_rate_hcw}.
#' @param prob_hospital_cond_hcw_preAdm Numeric in \code{[0,1]}. Probability that a pre-admission
#'   candidate infection occurs in the hospital setting while the HCW is working.
#' @param ppe_coverage_hcw Numeric in \code{[0,1]} or function(t). Coverage: probability that an HCW
#'   (source or receiver) has PPE. Applied as a source layer when the HCW parent is still working
#'   pre-admission, and as an independent receiver layer whenever the recipient is an HCW; each layer
#'   thins by \code{ppe_coverage_hcw(t) * ppe_efficacy}, and the two combine multiplicatively for
#'   pre-admission hospital events with HCW recipients (keep-probability
#'   \eqn{(1 - \mathrm{ppe\_coverage\_hcw}(t)\,\mathrm{ppe\_efficacy})^2}). Coverage is resolved at the
#'   absolute calendar time of each candidate hospital transmission event in which PPE applies.
#' @param ppe_efficacy Numeric in \code{[0,1]} (fixed scalar). Efficacy of PPE at preventing infection
#'   conditional on the HCW having it. Shared by the source and receiver PPE layers; combined with
#'   \code{ppe_coverage_hcw} as a single per-event thinning probability \code{ppe_coverage_hcw(t) * ppe_efficacy}.
#' @param prop_etu Numeric in \code{[0,1]} or function(t). Proportion of hospitalised cases managed
#'   in ETU/ETC care at time \code{t} (the time-varying "coverage" lever for hospital quarantine).
#'   The post-admission hospital quarantine efficacy is derived as the prop_etu(t)-weighted mixture
#'   \code{prop_etu(t) * etu_efficacy + (1 - prop_etu(t)) * general_hospital_quarantine_efficacy}.
#' @param etu_efficacy Numeric in \code{[0,1]} (fixed scalar). Post-admission quarantine efficacy
#'   for cases managed in ETU/ETC care.
#' @param general_hospital_quarantine_efficacy Numeric in \code{[0,1]} (fixed scalar). Post-admission
#'   quarantine efficacy for cases managed in general (non-ETU) hospital care.
#' @param obv_pep_enabled Logical scalar. If TRUE, applies an OBV PEP infection-prevention
#'   gate around the Swiss-cheese thinning step. The gate composes multiplicatively with the
#'   PPE/quarantine layers: a candidate must survive every protective layer (PPE source,
#'   PPE receiver, hospital quarantine) AND not be prevented by OBV efficacy to appear as a
#'   realised infection. See \code{apply_obv_pep_gate()} for the two-phase semantics.
#' @param obv_pep_coverage Numeric in \code{[0,1]} or function(t). Probability a
#'   pre-thinning eligible candidate receives OBV at calendar time \code{t}.
#' @param obv_pep_adherence Numeric in \code{[0,1]} or function(t). Probability an OBV recipient
#'   adheres sufficiently for efficacy to apply.
#' @param obv_pep_dpc Non-negative numeric or function(t). Days post challenge/exposure to first
#'   dose. The simplest working assumption is \code{obv_pep_dpc = 1}.
#' @param obv_pep_efficacy NULL, numeric in \code{[0,1]}, or function(dpc). If NULL, uses
#'   \code{obv_pep_efficacy_from_dpc()}, which is cut to zero after 10 DPC.
#' @param obv_pep_target_class Character vector of offspring classes eligible for OBV PEP.
#'   Defaults to \code{"HCW"}.
#' @param obv_pep_target_locations Character vector of exposure settings eligible for OBV PEP.
#'   Defaults to \code{"hospital"} for HCW occupational exposures.
#' @param prob_hcw_cond_hcw_comm Numeric in \code{[0,1]}. Probability that a community-located
#'   offspring generated by an HCW parent is an HCW.
#' @param prob_hcw_cond_hcw_hospital Numeric in \code{[0,1]}. Probability that a hospital-located
#'   offspring generated by an HCW parent is an HCW.
#' @export
offspring_function_hcw <- function(

  ## Characteristics and properties of the parent (who we are generating the offspring for)
  parent_info,

  ## Parameters of the offspring and generation time distributions for HCWs
  mn_offspring_hcw = NULL,                  # scalar or function(t): mean offspring distribution for HCWs (resolved at parent infection time)
  overdisp_offspring_hcw = NULL,            # overdispersion of the offspring distribution for HCWs
  Tg_shape_hcw = NULL,                      # gamma shape parameter for Tg distribution for HCWs
  Tg_rate_hcw = NULL,                       # gamma rate parameter for Tg distribution for HCWs

  ## Setting model for HCWs
  prob_hospital_cond_hcw_preAdm = NULL,     # probability that an infection generated prior to parent hospitaliation occurs in the hospital (whilst HCW is working)
  ppe_coverage_hcw = NULL,                  # scalar or function(t): coverage/probability that an HCW (source or receiver) has PPE
  ppe_efficacy = NULL,                      # scalar: efficacy of PPE conditional on the HCW having it
  prop_etu = NULL,                          # scalar/function(t): proportion of hospitalised cases in ETU/ETC care (time-varying coverage lever)
  etu_efficacy = NULL,                      # scalar: post-admission quarantine efficacy for ETU/ETC care
  general_hospital_quarantine_efficacy = NULL,  # scalar: post-admission quarantine efficacy for general (non-ETU) hospital care

  ## Obeldesivir PEP for exposed HCWs
  obv_pep_enabled = FALSE,
  obv_pep_coverage = 0,
  obv_pep_adherence = 1,
  obv_pep_dpc = 1,
  obv_pep_efficacy = NULL,
  obv_pep_target_class = "HCW",
  obv_pep_target_locations = "hospital",

  ## Probabilities for HCW infecting either genPop or HCWs, depending on the setting
  prob_hcw_cond_hcw_comm = NULL,            # prob that a community-located infection generated by HCW is a HCW
  prob_hcw_cond_hcw_hospital = NULL         # prob that a hospital-located infection generated by HCW is a HCW
) {

  ## Local helpers for parameters that can be either scalars or functions of
  ## absolute calendar time. The actual interpolation is handled by
  ## resolve_time_varying(), so this function stays scenario-agnostic.
  validate_probability_or_time_varying <- function(param, param_name) {
    if (is.function(param)) {
      return(invisible(NULL))
    }
    if (!is.numeric(param) || length(param) != 1L || is.na(param) || param < 0 || param > 1) {
      stop(sprintf("`%s` must be a function(t) or a single numeric in [0, 1].", param_name),
           call. = FALSE)
    }
    invisible(NULL)
  }

  validate_probability_scalar <- function(param, param_name) {
    if (!is.numeric(param) || length(param) != 1L || is.na(param) || param < 0 || param > 1) {
      stop(sprintf("`%s` must be a single numeric in [0, 1].", param_name),
           call. = FALSE)
    }
    invisible(NULL)
  }

  validate_positive_or_time_varying <- function(param, param_name) {
    if (is.function(param)) {
      return(invisible(NULL))
    }
    if (is.null(param) || !is.numeric(param) || length(param) != 1L || is.na(param) || param <= 0) {
      stop(sprintf("`%s` must be a function(t) or a single positive numeric value.", param_name),
           call. = FALSE)
    }
    invisible(NULL)
  }

  resolve_probability <- function(param, t, param_name) {
    value <- resolve_time_varying(param = param, t = t, param_name = param_name)
    if (any(value < 0 | value > 1)) {
      stop(sprintf("`%s` must resolve to value(s) in [0, 1].", param_name), call. = FALSE)
    }
    value
  }

  resolve_hospital_quarantine_efficacy <- function(t) {
    prop_etu_t <- resolve_probability(prop_etu, t, "prop_etu")

    ## Post-admission quarantine efficacy is a coverage-style mixture over where a
    ## hospitalised case is managed: a proportion prop_etu(t) receive the (higher)
    ## ETU/ETC quarantine efficacy and the remainder receive the general-hospital
    ## quarantine efficacy. Both efficacies are fixed scalars; the only time
    ## variation enters through prop_etu(t).
    hospital_quarantine_efficacy_t <-
      prop_etu_t * etu_efficacy +
      (1 - prop_etu_t) * general_hospital_quarantine_efficacy

    if (any(hospital_quarantine_efficacy_t < 0 |
            hospital_quarantine_efficacy_t > 1)) {
      stop(
        "`hospital_quarantine_efficacy(t)` must resolve to values between 0 and 1.",
        call. = FALSE
      )
    }

    hospital_quarantine_efficacy_t
  }

  # Step 0: Extract relevant parent information from parent_info
  parent_hospitalised = parent_info$hospitalisation                          # whether the parent (infector) is hospitalised or not
  parent_time_to_hospitalisation = parent_info$time_hospitalisation_relative # if parent is hospitalised, the time of hospitalisation (relative to infection)
  parent_time_to_outcome = parent_info$time_outcome_relative                 # the time when the parent dies/recovers (relative to time of infection)
  parent_time_infection_absolute = parent_info$time_infection_absolute       # absolute calendar time of parent infection

  #########################################################################################
  ## Checks to make sure function inputs are correctly specified
  #########################################################################################
  if (is.null(parent_hospitalised) || length(parent_hospitalised) != 1L || !is.logical(parent_hospitalised) || is.na(parent_hospitalised)) {
    stop("`parent_hospitalised` must be a single logical value: TRUE or FALSE.", call. = FALSE)
  }
  if (isTRUE(parent_hospitalised)) {
    if (is.null(parent_time_to_hospitalisation) || length(parent_time_to_hospitalisation) != 1L ||
        !is.numeric(parent_time_to_hospitalisation) || is.na(parent_time_to_hospitalisation) || parent_time_to_hospitalisation < 0) {
      stop("When `parent_hospitalised` is TRUE, `parent_time_to_hospitalisation` must be a single non-negative numeric value (not NA).", call. = FALSE)
    }
  }
  if (is.null(parent_time_to_outcome) || length(parent_time_to_outcome) != 1L ||
      !is.numeric(parent_time_to_outcome) || is.na(parent_time_to_outcome) || parent_time_to_outcome < 0) {
    stop("`parent_time_to_outcome` must be a single non-negative numeric value (not NA).", call. = FALSE)
  }
  if (is.null(parent_time_infection_absolute) || length(parent_time_infection_absolute) != 1L ||
      !is.numeric(parent_time_infection_absolute) || is.na(parent_time_infection_absolute)) {
    stop("`parent_info$time_infection_absolute` must be a single non-missing numeric value.", call. = FALSE)
  }
  if (identical(parent_hospitalised, FALSE)) {
    if (!is.na(parent_time_to_hospitalisation)) {
      stop("When `parent_hospitalised` is FALSE, `parent_time_to_hospitalisation` must be NA.", call. = FALSE)
    }
  }

  ## Parameter checks (positivity / bounds). mn_offspring_hcw is handled separately
  ## because it may be a scalar OR a function(t); the others are scalars.
  for (nm in c("overdisp_offspring_hcw", "Tg_shape_hcw", "Tg_rate_hcw")) {
    val <- get(nm, inherits = FALSE)
    if (is.null(val) || length(val) != 1L || !is.numeric(val) || is.na(val) || val <= 0) {
      stop(sprintf("`%s` must be a single positive numeric value.", nm), call. = FALSE)
    }
  }
  validate_positive_or_time_varying(mn_offspring_hcw, "mn_offspring_hcw")
  for (nm in c("prob_hospital_cond_hcw_preAdm", "prob_hcw_cond_hcw_comm", "prob_hcw_cond_hcw_hospital")) {
    val <- get(nm, inherits = FALSE)
    if (is.null(val) || length(val) != 1L || !is.numeric(val) || is.na(val) || val < 0 || val > 1) {
      stop(sprintf("`%s` must be a single numeric value in [0, 1].", nm), call. = FALSE)
    }
  }
  validate_probability_or_time_varying(ppe_coverage_hcw, "ppe_coverage_hcw")
  validate_probability_scalar(ppe_efficacy, "ppe_efficacy")
  validate_probability_or_time_varying(prop_etu, "prop_etu")
  validate_probability_scalar(etu_efficacy, "etu_efficacy")
  validate_probability_scalar(general_hospital_quarantine_efficacy, "general_hospital_quarantine_efficacy")

  ########################################################################################################
  ## Generating offspring, offspring infection times, offspring infection locations & offspring classes
  ########################################################################################################

  # Step 1: Draw from offspring distribution to produce raw number of offspring.
  #         mn_offspring_hcw may be time-varying; resolve it once at the parent's
  #         absolute infection time so the whole brood shares the parent's clock.
  mn_offspring_hcw_t <- resolve_positive_time_varying(
    mn_offspring_hcw, parent_time_infection_absolute, "mn_offspring_hcw")
  num_offspring_raw <- rnbinom(n = 1, mu = mn_offspring_hcw_t, size = overdisp_offspring_hcw)

  if (num_offspring_raw == 0L) {
    return(empty_offspring_dataframe())
  }

  # Step 2: Generate time of infection for each offspring based on the generation time (truncated at outcome)
  infection_times <- rtrunc_gamma(n = num_offspring_raw,
                                  lower = 0,
                                  upper = parent_time_to_outcome,
                                  Tg_shape = Tg_shape_hcw,
                                  Tg_rate = Tg_rate_hcw)
  infection_times_absolute <- parent_time_infection_absolute + infection_times

  # Step 3: Generate location of infection, noting that for HCWs, pre-hospitalisation infections can be community *or* hospital (while working). This is
  #         controlled via prob_hospital_cond_hcw_preAdm. Post-hospitalisation events are necessarily hospital.
  t_hosp <- if (isTRUE(parent_hospitalised)) parent_time_to_hospitalisation else Inf
  if (is.finite(t_hosp) && parent_time_to_outcome <= t_hosp) t_hosp <- Inf
  pre_admission <- infection_times < t_hosp
  is_hosp_pre_admission <- as.logical(rbinom(n = length(infection_times), size = 1, prob = prob_hospital_cond_hcw_preAdm))
  infection_settings <- ifelse(pre_admission, ifelse(is_hosp_pre_admission, "hospital", "community"), "hospital")

  # Step 4: Assign class (HCW or genPop) to each offspring based on setting. Class is assigned BEFORE
  #         thinning so that receiver PPE can be applied class-specifically to HCW recipients.
  offspring_class <- rep("genPop", length(infection_times))
  prob_hcw <- ifelse(infection_settings == "community", prob_hcw_cond_hcw_comm, prob_hcw_cond_hcw_hospital)
  flip_hcw <- as.logical(rbinom(n = length(infection_times), size = 1, prob = prob_hcw))
  offspring_class[flip_hcw] <- "HCW"

  # Step 5: Compute per-event keep probability under three independent protective layers
  #         (Swiss-cheese multiplicative), each applied only where it is relevant.
  #   - Source PPE (worn by the still-working HCW parent): applies to all PRE-admission hospital events.
  #   - Receiver PPE (worn by HCW recipients treating the source): applies to all hospital events with
  #     an HCW recipient (pre- or post-admission).
  #     Both PPE layers thin by coverage times conditional efficacy: ppe_coverage_hcw(t) * ppe_efficacy,
  #     sharing the same coverage curve and the same (fixed) efficacy for the source and receiver roles.
  #   - Hospital quarantine (source is now an isolated HCW patient): applies to all POST-admission
  #     hospital events. Resolved at the absolute calendar time of each candidate hospital transmission
  #     as a prop_etu(t) mixture of the (fixed) ETU and general-hospital quarantine efficacies:
  #       hospital_quarantine_efficacy(t) = prop_etu(t) * etu_efficacy + (1 - prop_etu(t)) * general_hospital_quarantine_efficacy
  #   Hospital keep-probability = (1 - ppe_source_cov * ppe_efficacy) * (1 - ppe_receiver_cov * ppe_efficacy) * (1 - hq),
  #   with each factor degenerating to 1 where the corresponding layer does not apply.
  p_keep_infection <- rep(1, length(infection_times))
  hospital_idx <- which(infection_settings == "hospital")
  if (length(hospital_idx) > 0) {
    pre_adm_in_hospital  <- pre_admission[hospital_idx]
    post_adm_in_hospital <- !pre_adm_in_hospital
    hcw_recv             <- offspring_class[hospital_idx] == "HCW"

    ppe_source_cov_t <- numeric(length(hospital_idx))
    if (any(pre_adm_in_hospital)) {
      ppe_source_cov_t[pre_adm_in_hospital] <- resolve_probability(
        ppe_coverage_hcw,
        infection_times_absolute[hospital_idx[pre_adm_in_hospital]],
        "ppe_coverage_hcw"
      )
    }

    ppe_recv_cov_t <- numeric(length(hospital_idx))
    if (any(hcw_recv)) {
      ppe_recv_cov_t[hcw_recv] <- resolve_probability(
        ppe_coverage_hcw,
        infection_times_absolute[hospital_idx[hcw_recv]],
        "ppe_coverage_hcw"
      )
    }

    hq_t <- numeric(length(hospital_idx))
    if (any(post_adm_in_hospital)) {
      hq_t[post_adm_in_hospital] <- resolve_hospital_quarantine_efficacy(
        infection_times_absolute[hospital_idx[post_adm_in_hospital]]
      )
    }

    p_keep_infection[hospital_idx] <- (1 - ppe_source_cov_t * ppe_efficacy) * (1 - ppe_recv_cov_t * ppe_efficacy) * (1 - hq_t)
  }

  # Step 5b: Snapshot the pre-thinning candidate set for the two-phase OBV PEP gate.
  pre_thinning <- list(
    infection_location      = infection_settings,
    offspring_class         = offspring_class,
    infection_time_absolute = infection_times_absolute
  )

  # Step 6: Thin (Swiss-cheese; OBV efficacy is applied separately, post-thinning, below)
  keep_infection <- as.logical(rbinom(n = length(infection_times), size = 1, prob = p_keep_infection))

  # Step 7: OBV PEP gate (two phases internally, see apply_obv_pep_gate). Treatment
  #         status (received, adherent, dpc) is decided on the pre-thinning set so the
  #         "treat-all-contacts" denominator is captured; efficacy then thins infections
  #         only among kept-and-adherent candidates.
  obv_gate <- apply_obv_pep_gate(
    pre_thinning             = pre_thinning,
    kept_indices             = which(keep_infection),
    obv_pep_enabled          = obv_pep_enabled,
    obv_pep_coverage     = obv_pep_coverage,
    obv_pep_adherence        = obv_pep_adherence,
    obv_pep_dpc              = obv_pep_dpc,
    obv_pep_efficacy         = obv_pep_efficacy,
    obv_pep_target_class     = obv_pep_target_class,
    obv_pep_target_locations = obv_pep_target_locations
  )

  ## Final realised set = kept AND not prevented by OBV.
  final_local        <- obv_gate$keep
  final_idx          <- which(keep_infection)[final_local]
  infection_times    <- infection_times[final_idx]
  infection_settings <- infection_settings[final_idx]
  offspring_class    <- offspring_class[final_idx]
  obv_metadata       <- obv_gate$metadata[final_local, , drop = FALSE]

  # Step 8: Define and output dataframe with the results
  offspring_df <- data.frame(infection_location = infection_settings,
                             time_infection_relative = infection_times,
                             class = offspring_class,
                             obv_metadata,
                             stringsAsFactors = FALSE)
  attr(offspring_df, "obv_pep_num_treated") <- obv_gate$num_treated
  ## Stash the infections OBV prevented (no RNG drawn) so the caller can resolve
  ## their counterfactual would-be deaths after the simulation loop.
  attr(offspring_df, "obv_pep_prevented_info") <-
    extract_obv_prevented_info(pre_thinning, keep_infection, final_local)

  return(offspring_df)
}
